UPDATE quizzes SET video_url = NULL WHERE slug IN ('tabelas-verdade-conectivos', 'estruturas-condicionais', 'estruturas-de-repeticao');
UPDATE quiz_translations SET video_url = NULL WHERE quiz_id IN (SELECT id FROM quizzes WHERE slug IN ('tabelas-verdade-conectivos', 'estruturas-condicionais', 'estruturas-de-repeticao'));
UPDATE quizzes SET description = 'Teste o que você sabe sobre conjunção, disjunção, negação, bicondicional, tautologias e expressões compostas.' WHERE slug = 'tabelas-verdade-conectivos';
UPDATE quiz_translations SET description = 'Test what you know about conjunction, disjunction, negation, biconditional, tautologies and compound expressions.' WHERE locale = 'en' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'tabelas-verdade-conectivos');
UPDATE quiz_translations SET description = 'Pon a prueba lo que sabes sobre conjunción, disyunción, negación, bicondicional, tautologías y expresiones compuestas.' WHERE locale = 'es' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'tabelas-verdade-conectivos');
UPDATE quiz_translations SET description = 'Testez vos connaissances sur la conjonction, la disjonction, la négation, le biconditionnel, les tautologies et les expressions composées.' WHERE locale = 'fr' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'tabelas-verdade-conectivos');
UPDATE quizzes SET description = 'Pratique se/senão, condições encadeadas e aninhadas, escolha/caso e operadores lógicos com fluxogramas e pseudocódigo.' WHERE slug = 'estruturas-condicionais';
UPDATE quiz_translations SET description = 'Practice if/else, chained and nested conditions, switch/case and logical operators with flowcharts and pseudocode.' WHERE locale = 'en' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'estruturas-condicionais');
UPDATE quiz_translations SET description = 'Practica si/si no, condiciones encadenadas y anidadas, según/caso y operadores lógicos con diagramas de flujo y pseudocódigo.' WHERE locale = 'es' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'estruturas-condicionais');
UPDATE quiz_translations SET description = 'Entraînez-vous avec si/sinon, les conditions enchaînées et imbriquées, selon/cas et les opérateurs logiques à l’aide d’organigrammes et de pseudocode.' WHERE locale = 'fr' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'estruturas-condicionais');
UPDATE quizzes SET description = 'Treine enquanto, para com passo, repita...até, acumuladores, laços aninhados e laço infinito com teste de mesa.' WHERE slug = 'estruturas-de-repeticao';
UPDATE quiz_translations SET description = 'Practice while, for with step, repeat...until, accumulators, nested loops and infinite loops with desk checking.' WHERE locale = 'en' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'estruturas-de-repeticao');
UPDATE quiz_translations SET description = 'Practica mientras, para con paso, repetir...hasta que, acumuladores, bucles anidados y bucle infinito con prueba de escritorio.' WHERE locale = 'es' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'estruturas-de-repeticao');
UPDATE quiz_translations SET description = 'Entraînez-vous avec tant que, pour avec pas, répéter...jusqu’à, les accumulateurs, les boucles imbriquées et la boucle infinie avec l’exécution pas à pas.' WHERE locale = 'fr' AND quiz_id = (SELECT id FROM quizzes WHERE slug = 'estruturas-de-repeticao');
